{
  "items": [
    {
      "name": "ConditionallyCompleteLattice.csSup_le",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_5} [self : ConditionallyCompleteLattice α] (s : Set α) (a : α),\n  s.Nonempty → a ∈ upperBounds s → sSup s ≤ a"
    },
    {
      "name": "Real.sSup_le",
      "module_name": "Mathlib.Data.Real.Archimedean",
      "kind": "theorem",
      "type": "∀ {s : Set ℝ} {a : ℝ}, (∀ x ∈ s, x ≤ a) → 0 ≤ a → sSup s ≤ a"
    },
    {
      "name": "sSup_le",
      "module_name": "Mathlib.Order.CompleteLattice.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : CompleteSemilatticeSup α] {s : Set α} {a : α}, (∀ b ∈ s, b ≤ a) → sSup s ≤ a"
    },
    {
      "name": "isLUB_sSup",
      "module_name": "Mathlib.Order.CompleteLattice.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : CompleteSemilatticeSup α] (s : Set α), IsLUB s (sSup s)"
    },
    {
      "name": "Real.isLUB_sSup",
      "module_name": "Mathlib.Data.Real.Archimedean",
      "kind": "theorem",
      "type": "∀ {s : Set ℝ}, s.Nonempty → BddAbove s → IsLUB s (sSup s)"
    }
  ]
}
